/** Central durable coordinator. Workers receive public allowlisted sources, never private content. */
public final class AgentService implements AutoCloseable {
  @FunctionalInterface public interface PublicationSink {Map<String,Object> submit(String actor,Map<String,Object> draft)throws Exception;}
  public record EvidenceProof(boolean verified,String reason,List<Map<String,Object>>receipts,Map<String,Object>trustedSuggestion,long inputTokens,long outputTokens){public EvidenceProof{receipts=List.copyOf(receipts);trustedSuggestion=Map.copyOf(trustedSuggestion);}public EvidenceProof(boolean verified,String reason,List<Map<String,Object>>receipts){this(verified,reason,receipts,Map.of(),0,0);}}
  @FunctionalInterface public interface EvidenceVerifier{EvidenceProof verify(Map<String,Object> leasedPolicy,List<Map<String,Object>> observations,Map<String,Object> draft)throws Exception;}
  private final CommunityStore store;private final AccessControl access;private final PublicationSink sink;private final EvidenceVerifier evidenceVerifier;
  private final SecureRandom random=new SecureRandom();private final AgentPageCursor pageCursors=new AgentPageCursor();private ScheduledExecutorService scheduler;private volatile LocalLibraryLinks libraryLinks;
  private static final int MAX_JOBS=2000,MAX_SOURCES=1000,MAX_CITIES=1000,INPUT_RESERVATION=100000;
  public AgentService(CommunityStore store,AccessControl access,PublicationSink sink)throws Exception{this(store,access,sink,new TrustedEditorialVerifier());}
  public AgentService(CommunityStore store,AccessControl access,PublicationSink sink,EvidenceVerifier verifier)throws Exception{this.store=store;this.access=access;this.sink=sink;this.evidenceVerifier=Objects.requireNonNull(verifier);initialize();}
  private void initialize()throws Exception{store.tx(db->{try(var s=db.createStatement()){
    s.execute("CREATE TABLE IF NOT EXISTS agent_config(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL,data BLOB NOT NULL,last_cycle INTEGER NOT NULL)");
    s.execute("CREATE TABLE IF NOT EXISTS agent_city(id TEXT PRIMARY KEY,name TEXT NOT NULL,last_success INTEGER NOT NULL DEFAULT 0)");
    s.execute("CREATE TABLE IF NOT EXISTS agent_source(id TEXT PRIMARY KEY,url TEXT NOT NULL UNIQUE,city TEXT NOT NULL REFERENCES agent_city(id),source_group TEXT NOT NULL,official INTEGER NOT NULL,enabled INTEGER NOT NULL,min_interval INTEGER NOT NULL,lawful_basis TEXT NOT NULL,last_fetch INTEGER NOT NULL DEFAULT 0)");
    s.execute("CREATE TABLE IF NOT EXISTS agent_host(host TEXT PRIMARY KEY,next_fetch INTEGER NOT NULL)");
    s.execute("CREATE TABLE IF NOT EXISTS agent_worker(identity TEXT PRIMARY KEY REFERENCES identities(identity),enabled INTEGER NOT NULL,last_seen INTEGER NOT NULL DEFAULT 0)");
    s.execute("CREATE TABLE IF NOT EXISTS agent_job(id TEXT PRIMARY KEY,city TEXT NOT NULL REFERENCES agent_city(id),created INTEGER NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL,lease_owner TEXT NOT NULL DEFAULT '',lease_hash TEXT NOT NULL DEFAULT '',lease_until INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 0,reserved INTEGER NOT NULL DEFAULT 0,day TEXT NOT NULL DEFAULT '',payload BLOB,result BLOB,last_error TEXT NOT NULL DEFAULT '')");
    s.execute("CREATE INDEX IF NOT EXISTS agent_job_queue ON agent_job(state,next_attempt)");
    s.execute("CREATE TABLE IF NOT EXISTS agent_budget(day TEXT PRIMARY KEY,charged INTEGER NOT NULL,requests INTEGER NOT NULL,tokens INTEGER NOT NULL)");
    s.execute("CREATE TABLE IF NOT EXISTS agent_candidate(id TEXT PRIMARY KEY,dedupe TEXT NOT NULL UNIQUE,job TEXT NOT NULL,state TEXT NOT NULL,draft BLOB NOT NULL,content_id TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL,proof BLOB,verify_token TEXT NOT NULL DEFAULT '',verify_until INTEGER NOT NULL DEFAULT 0,verify_attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '')");
    s.execute("CREATE INDEX IF NOT EXISTS agent_candidate_pending ON agent_candidate(state,created)");
    s.execute("CREATE TABLE IF NOT EXISTS agent_seen_evidence(url TEXT PRIMARY KEY,candidate TEXT NOT NULL REFERENCES agent_candidate(id))");
    s.execute("CREATE TABLE IF NOT EXISTS agent_diagnostic(id INTEGER PRIMARY KEY AUTOINCREMENT,created INTEGER NOT NULL,kind TEXT NOT NULL,detail TEXT NOT NULL)");
  }ensureColumn(db,"agent_job","result","BLOB");ensureColumn(db,"agent_candidate","proof","BLOB");ensureColumn(db,"agent_candidate","verify_token","TEXT NOT NULL DEFAULT ''");ensureColumn(db,"agent_candidate","verify_until","INTEGER NOT NULL DEFAULT 0");ensureColumn(db,"agent_candidate","verify_attempts","INTEGER NOT NULL DEFAULT 0");exec(db,"INSERT OR IGNORE INTO agent_config VALUES(1,1,?,0)",AgentJson.bytes(defaultConfig()));return null;});}
  public void enforceWorkerBoundary(String actor,String action)throws Exception{boolean restricted=store.tx(db->exists(db,"SELECT 1 FROM agent_worker WHERE identity=?",actor))||access.permissions(actor,"GLOBAL").contains("AGENT_WORK");if(restricted&&!Set.of("agent.worker.claim","agent.worker.complete","agent.worker.fail").contains(action))throw CommunityException.denied();}
  public void setLibraryLinks(LocalLibraryLinks links){this.libraryLinks=Objects.requireNonNull(links);}
  public boolean supports(String action){return action!=null&&action.startsWith("agent.");}
  public Map<String,Object> handle(String actor,String action,Map<String,Object> d)throws Exception{
    if(action.equals("agent.cities.list")){access.authorizationEpoch(actor);return store.tx(db->listPage(db,actor,action,d));}
    if(action.equals("agent.library.suggestion.get")){LocalLibraryLinks links=libraryLinks;if(links==null)throw CommunityException.missing();return links.poll(actor,d);}
    if(action.equals("agent.library.suggest")){LocalLibraryLinks links=libraryLinks;if(links==null)throw new CommunityException("MODEL_UNAVAILABLE","Локальная модель связей не настроена");Map<String,Object> policy=store.tx(this::config);if(!"ollama".equals(policy.get("provider")))throw new CommunityException("LOCAL_MODEL_REQUIRED","Закрытые материалы доступны только локальной модели");return links.request(actor,d,URI.create(text(policy,"endpoint",2048)),text(policy,"model",128));}
    if(action.equals("agent.worker.claim"))return claim(actor);
    if(action.equals("agent.worker.complete"))return complete(actor,d);
    if(action.equals("agent.worker.fail"))return fail(actor,d);
    return store.tx(db->{access.require(actor,"AGENT_MANAGE","GLOBAL");return switch(action){
      case "agent.status" ->status(db);
      case "agent.sources.list" ->listPage(db,actor,action,d);
      case "agent.cities.put" ->cityPut(db,actor,d);
      case "agent.sources.put" ->sourcePut(db,actor,d);
      case "agent.config.set" ->configSet(db,actor,d);
      case "agent.workers.list" ->listPage(db,actor,action,d);
      case "agent.workers.put" ->workerPut(db,actor,d);
      case "agent.jobs.list" ->listPage(db,actor,action,d);
      case "agent.review.list" ->listPage(db,actor,action,d);
      case "agent.cycle" ->{cycle();yield status(db);}
      default ->throw CommunityException.invalid();};});
  }
  private static Map<String,Object> defaultConfig(){Map<String,Object> m=new LinkedHashMap<>();m.put("enabled",false);m.put("intervalMinutes",20);m.put("provider","");m.put("model","");m.put("endpoint","");m.put("credentialRef","");m.put("publisherIdentity","");m.put("maxOutputTokens",1024);m.put("dailyBudgetMicros",0);m.put("dailyRequestLimit",100);m.put("dailyTokenLimit",1000000);m.put("inputMicrosPerMillion",0);m.put("outputMicrosPerMillion",0);m.put("autoPublish",false);m.put("allowGlobal",false);return m;}
  private Map<String,Object> config(Connection db)throws Exception{try(var s=db.createStatement();var r=s.executeQuery("SELECT data FROM agent_config WHERE id=1")){r.next();return AgentJson.object(r.getBytes(1),32768);}}
  private long revision(Connection db)throws SQLException{try(var s=db.createStatement();var r=s.executeQuery("SELECT revision FROM agent_config WHERE id=1")){r.next();return r.getLong(1);}}
  private Map<String,Object> configSet(Connection db,String actor,Map<String,Object>d)throws Exception{
    keys(d,Set.of("enabled","intervalMinutes","provider","model","endpoint","credentialRef","publisherIdentity","maxOutputTokens","dailyBudgetMicros","dailyRequestLimit","dailyTokenLimit","inputMicrosPerMillion","outputMicrosPerMillion","autoPublish","allowGlobal","requestId","stepUp"));
    access.requireStepUp(actor,d);Map<String,Object> c=new LinkedHashMap<>(defaultConfig());for(String k:c.keySet())if(d.containsKey(k))c.put(k,d.get(k));
    bool(c,"enabled");number(c,"intervalMinutes",15,30);String provider=text(c,"provider",32),model=text(c,"model",128),endpoint=text(c,"endpoint",2048);boolean enabled=bool(c,"enabled");
    if(!provider.isEmpty()&&!Set.of("ollama","openai-compatible").contains(provider)||!model.isEmpty()&&!model.matches("[A-Za-z0-9][A-Za-z0-9._:/@-]{0,127}"))throw CommunityException.invalid();
    if(enabled&&(provider.isEmpty()||model.isEmpty()||endpoint.isEmpty()))throw new CommunityException("MODEL_REQUIRED","Выберите модель перед включением агента");
    if(!endpoint.isEmpty())modelEndpoint(provider,endpoint);
    String ref=text(c,"credentialRef",80);if(!ref.isEmpty()&&!ref.matches("AEGIS_NEWS_API_KEY_[A-Z0-9_]{1,48}"))throw CommunityException.invalid();
    String publisher=text(c,"publisherIdentity",64);if(!publisher.isEmpty())Values.identity(publisher);if(enabled&&publisher.isEmpty())throw CommunityException.invalid();
    number(c,"maxOutputTokens",128,4096);number(c,"dailyBudgetMicros",0,1000000000);number(c,"dailyRequestLimit",1,10000);number(c,"dailyTokenLimit",100000,1000000000);number(c,"inputMicrosPerMillion",0,1000000000);number(c,"outputMicrosPerMillion",0,1000000000);bool(c,"autoPublish");bool(c,"allowGlobal");
    if(provider.equals("openai-compatible")&&(number(c,"inputMicrosPerMillion",0,1000000000)==0||number(c,"outputMicrosPerMillion",0,1000000000)==0))throw new CommunityException("PRICE_REQUIRED","Для внешнего API задайте консервативные верхние тарифы");
    return access.executeCritical(actor,Values.string(d,"requestId",36),"AGENT_CONFIG",CanonicalJson.encode(CanonicalJson.operationFields(d)),tx->{exec(tx,"UPDATE agent_config SET data=?,revision=revision+1 WHERE id=1",AgentJson.bytes(c));diagnostic(tx,"CONFIG_CHANGED","Конфигурация изменена двумя администраторами");store.audit(tx,actor,"AGENT_CONFIG","agent","No credentials stored; model="+model);return status(tx);});
  }
  private static void modelEndpoint(String provider,String endpoint)throws Exception{URI u=URI.create(endpoint);if(u.getHost()==null||u.getRawUserInfo()!=null||u.getRawQuery()!=null||u.getRawFragment()!=null)throw CommunityException.invalid();if(provider.equals("ollama")){if(!u.getScheme().equals("http")||!Set.of("127.0.0.1","[::1]","::1").contains(u.getHost())||!u.getPath().equals("/api/chat"))throw CommunityException.invalid();}else if(!provider.equals("openai-compatible")||!u.getScheme().equals("https")||u.getPort()!=-1&&u.getPort()!=443||!u.getPath().endsWith("/chat/completions"))throw CommunityException.invalid();}
  private Map<String,Object> cityPut(Connection db,String actor,Map<String,Object>d)throws Exception{keys(d,Set.of("id","name","stepUp"));access.requireStepUp(actor,d);String id=city(text(d,"id",160)),name=text(d,"name",160);if(name.isBlank())throw CommunityException.invalid();if(count(db,"agent_city")>=MAX_CITIES&&!exists(db,"SELECT 1 FROM agent_city WHERE id=?",id))throw limit();exec(db,"INSERT INTO agent_city(id,name) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name",id,name);store.audit(db,actor,"AGENT_CITY",id,"Registered explicitly; no IP geolocation");return Map.of("id",id,"name",name);}
  private Map<String,Object> sourcePut(Connection db,String actor,Map<String,Object>d)throws Exception{
    keys(d,Set.of("sourceId","url","cityId","independenceGroup","official","enabled","minIntervalMinutes","lawfulBasis","requestId","stepUp"));access.requireStepUp(actor,d);
    String id=text(d,"sourceId",36);if(id.isEmpty())id=UUID.randomUUID().toString();else uuid(id);String url=text(d,"url",2048),city=city(text(d,"cityId",160)),group=text(d,"independenceGroup",120),law=text(d,"lawfulBasis",1000);sourceUrl(url);if(group.isBlank()||law.isBlank()||!exists(db,"SELECT 1 FROM agent_city WHERE id=?",city))throw CommunityException.invalid();long interval=number(d,"minIntervalMinutes",15,10080);boolean official=bool(d,"official"),enabled=bool(d,"enabled");if(count(db,"agent_source")>=MAX_SOURCES&&!exists(db,"SELECT 1 FROM agent_source WHERE id=?",id))throw limit();String sourceId=id;
    return access.executeCritical(actor,Values.string(d,"requestId",36),"AGENT_CONFIG",CanonicalJson.encode(CanonicalJson.operationFields(d)),tx->{exec(tx,"INSERT INTO agent_source(id,url,city,source_group,official,enabled,min_interval,lawful_basis) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET url=excluded.url,city=excluded.city,source_group=excluded.source_group,official=excluded.official,enabled=excluded.enabled,min_interval=excluded.min_interval,lawful_basis=excluded.lawful_basis",sourceId,url,city,group,official?1:0,enabled?1:0,interval,law);exec(tx,"UPDATE agent_config SET revision=revision+1 WHERE id=1");store.audit(tx,actor,"AGENT_SOURCE",sourceId,"Allowlist policy changed");return Map.of("id",sourceId);});
  }
  private Map<String,Object> workerPut(Connection db,String actor,Map<String,Object>d)throws Exception{keys(d,Set.of("identity","enabled","requestId","stepUp"));access.requireStepUp(actor,d);String id=Values.identity(text(d,"identity",64));boolean enabled=bool(d,"enabled");if(!exists(db,"SELECT 1 FROM identities WHERE identity=?",id)||access.isGlobalAdmin(id)||!access.permissions(id,"GLOBAL").equals(Set.of("AGENT_WORK")))throw new CommunityException("WORKER_PRIVILEGE","Рабочая учётная запись должна иметь только служебные полномочия");return access.executeCritical(actor,Values.string(d,"requestId",36),"AGENT_CONFIG",CanonicalJson.encode(CanonicalJson.operationFields(d)),tx->{exec(tx,"INSERT INTO agent_worker(identity,enabled) VALUES(?,?) ON CONFLICT(identity) DO UPDATE SET enabled=excluded.enabled",id,enabled?1:0);if(!enabled)exec(tx,"UPDATE agent_job SET state='AVAILABLE',lease_until=0,next_attempt=? WHERE state='LEASED' AND lease_owner=?",now(),id);store.audit(tx,actor,"AGENT_WORKER",id,enabled?"enabled":"revoked");return Map.of("identity",id,"enabled",enabled);});}
  private Map<String,Object> status(Connection db)throws Exception{Map<String,Object> m=new LinkedHashMap<>(config(db));m.remove("credentialRef");m.put("revision",revision(db));m.put("modelProvider",m.get("provider"));m.put("pausedReason",!Boolean.TRUE.equals(m.get("enabled"))?"Агент выключен":Objects.toString(m.get("model"),"").isEmpty()?"Модель не настроена":"");for(String state:List.of("AVAILABLE","LEASED","COMPLETE","FAILED"))m.put(state.toLowerCase(Locale.ROOT),countWhere(db,"agent_job","state",state));m.put("queued",m.get("available"));m.put("review",countWhere(db,"agent_candidate","state","REVIEW"));try(var s=db.createStatement();var r=s.executeQuery("SELECT last_cycle FROM agent_config WHERE id=1")){r.next();m.put("lastCycle",r.getLong(1));}try(var q=db.prepareStatement("SELECT charged,requests,tokens FROM agent_budget WHERE day=?")){q.setString(1,day());try(var r=q.executeQuery()){m.put("budgetReservedMicros",r.next()?r.getLong(1):0);}}m.put("budgetLimitMicros",m.get("dailyBudgetMicros"));return m;}
  private List<Map<String,Object>> cities(Connection db)throws SQLException{List<Map<String,Object>>list=new ArrayList<>();try(var s=db.createStatement();var r=s.executeQuery("SELECT * FROM agent_city ORDER BY id LIMIT 1000")){while(r.next())list.add(Map.of("id",r.getString("id"),"name",r.getString("name"),"lastSuccessfulCrawl",r.getLong("last_success")));}return list;}
  private List<Map<String,Object>> sources(Connection db,String city,boolean due)throws SQLException{List<Map<String,Object>>list=new ArrayList<>();String sql="SELECT * FROM agent_source"+(city==null?"":" WHERE city=?"+(due?" AND enabled=1 AND last_fetch+min_interval*60000<=?":""))+" ORDER BY last_fetch,id LIMIT 1000";try(var q=db.prepareStatement(sql)){if(city!=null){q.setString(1,city);if(due)q.setLong(2,now());}try(var r=q.executeQuery()){while(r.next()){Map<String,Object>m=new LinkedHashMap<>();for(String k:List.of("id","url","city","source_group","lawful_basis"))m.put(switch(k){case "city"->"cityId";case "source_group"->"independenceGroup";case "lawful_basis"->"lawfulBasis";default->k;},r.getString(k));m.put("official",r.getInt("official")!=0);m.put("enabled",r.getInt("enabled")!=0);m.put("minIntervalMinutes",r.getLong("min_interval"));m.put("lastFetch",r.getLong("last_fetch"));list.add(m);}}}return list;}
  /** Keyset pages stay below the shared 8192-node JSON limit, including the signed HTTP envelope. */
  private Map<String,Object> listPage(Connection db,String actor,String action,Map<String,Object>d)throws Exception{
    keys(d,Set.of("limit","cursor"));int limit;String token;
    try{limit=(int)(d.containsKey("limit")?number(d,"limit",1,100):action.equals("agent.review.list")?25:50);token=d.containsKey("cursor")?text(d,"cursor",2048):"";}
    catch(IOException invalid){throw CommunityException.invalid();}
    long epoch=access.authorizationEpoch(actor);
    AgentPageCursor.Position position=token.isEmpty()?null:pageCursors.decode(token,actor,action,epoch,now());
    String table,key,property;boolean descending=false;
    switch(action){case "agent.sources.list"->{table="agent_source";key="id";property="sources";}
      case "agent.cities.list"->{table="agent_city";key="id";property="cities";}
      case "agent.workers.list"->{table="agent_worker";key="identity";property="workers";}
      case "agent.jobs.list"->{table="agent_job";key="id";property="jobs";descending=true;}
      case "agent.review.list"->{table="agent_candidate";key="id";property="items";descending=true;}
      default->throw CommunityException.invalid();}
    String where=position==null?"":descending?" WHERE (created<? OR (created=? AND id<?))":" WHERE "+key+">?";
    String sql="SELECT * FROM "+table+where+(descending?" ORDER BY created DESC,id DESC":" ORDER BY "+key)+" LIMIT ?";
    List<Map<String,Object>>rows=new ArrayList<>();AgentPageCursor.Position last=null;boolean more=false;int nodes=32,bytes=2048;
    try(var q=db.prepareStatement(sql)){int parameter=1;if(position!=null){if(descending){q.setLong(parameter++,position.created());q.setLong(parameter++,position.created());}q.setString(parameter++,position.id());}q.setInt(parameter,limit+1);
      try(var r=q.executeQuery()){while(r.next()){if(rows.size()==limit){more=true;break;}Map<String,Object>row=listRow(action,r);int rowNodes=jsonNodes(row),rowBytes=AgentJson.bytes(row).length;
        if(nodes+rowNodes>6000||bytes+rowBytes>1024*1024){if(rows.isEmpty())throw CommunityException.invalid();more=true;break;}
        rows.add(row);nodes+=rowNodes;bytes+=rowBytes;last=new AgentPageCursor.Position(r.getString(key),descending?r.getLong("created"):0);}}}
    String next=more?pageCursors.encode(actor,action,epoch,Objects.requireNonNull(last),now()):"";
    return Map.of(property,rows,"nextCursor",next,"hasMore",more,"limit",limit);
  }
  private static int jsonNodes(Object value){int n=1;if(value instanceof Map<?,?>m)for(Object child:m.values())n+=jsonNodes(child);else if(value instanceof Collection<?>list)for(Object child:list)n+=jsonNodes(child);return n;}
  private Map<String,Object> listRow(String action,ResultSet r)throws Exception{return switch(action){
    case "agent.cities.list"->Map.of("id",r.getString("id"),"name",r.getString("name"),"lastSuccessfulCrawl",r.getLong("last_success"));
    case "agent.sources.list"->{Map<String,Object>m=new LinkedHashMap<>();for(String k:List.of("id","url","city","source_group","lawful_basis"))m.put(switch(k){case "city"->"cityId";case "source_group"->"independenceGroup";case "lawful_basis"->"lawfulBasis";default->k;},r.getString(k));m.put("official",r.getInt("official")!=0);m.put("enabled",r.getInt("enabled")!=0);m.put("minIntervalMinutes",r.getLong("min_interval"));m.put("lastFetch",r.getLong("last_fetch"));yield m;}
    case "agent.workers.list"->Map.of("identity",r.getString("identity"),"enabled",r.getInt("enabled")!=0,"lastSeen",r.getLong("last_seen"));
    case "agent.jobs.list"->Map.of("id",r.getString("id"),"cityId",r.getString("city"),"state",r.getString("state"),"attempts",r.getInt("attempts"),"createdAt",r.getLong("created"),"lastError",r.getString("last_error"));
    case "agent.review.list"->Map.of("id",r.getString("id"),"state",r.getString("state"),"draft",AgentJson.object(r.getBytes("draft"),32768),"contentId",r.getString("content_id"),"lastError",r.getString("last_error"));
    default->throw CommunityException.invalid();};}
  /** One short scheduler thread; public network/model work happens only in separate worker processes. */
  public synchronized void start(){if(scheduler!=null)return;scheduler=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"aegis-news-coordinator");t.setDaemon(true);return t;});scheduler.scheduleWithFixedDelay(()->{try{cycle();drainOutbox();}catch(Exception e){try{store.tx(db->{diagnostic(db,"CYCLE_FAILED","Цикл не завершён; подробности не содержат секретов");return null;});}catch(Exception ignored){}}},0,30,TimeUnit.SECONDS);}
  public void cycle()throws Exception{store.tx(db->{Map<String,Object> c=config(db);if(!bool(c,"enabled")||text(c,"model",128).isEmpty())return null;long last;try(var s=db.createStatement();var r=s.executeQuery("SELECT last_cycle FROM agent_config WHERE id=1")){r.next();last=r.getLong(1);}if(last>0&&now()-last<number(c,"intervalMinutes",15,30)*60000)return null;
    exec(db,"UPDATE agent_job SET state=CASE WHEN attempts>=4 THEN 'FAILED' ELSE 'AVAILABLE' END,next_attempt=?,lease_until=0,last_error='Истекло время рабочего узла' WHERE state='LEASED' AND lease_until<?",now()+60000,now());
    // Prune only terminal diagnostics/jobs; dedupe and candidates remain bounded with explicit backpressure.
    exec(db,"DELETE FROM agent_job WHERE state IN ('COMPLETE','FAILED') AND created<?",now()-30L*86400000);exec(db,"DELETE FROM agent_budget WHERE day<?",LocalDate.now(store.clock()).minusDays(90).toString());
    for(Map<String,Object> city:cities(db)){if(count(db,"agent_job")>=MAX_JOBS)break;String id=(String)city.get("id");if(sources(db,id,true).isEmpty()||exists(db,"SELECT 1 FROM agent_job WHERE city=? AND state IN ('AVAILABLE','LEASED')",id))continue;exec(db,"INSERT INTO agent_job(id,city,created,state,next_attempt) VALUES(?,?,?,'AVAILABLE',?)",UUID.randomUUID().toString(),id,now(),now());}
    exec(db,"UPDATE agent_config SET last_cycle=? WHERE id=1",now());return null;});}
  private void worker(Connection db,String actor)throws Exception{access.require(actor,"AGENT_WORK","GLOBAL");if(!exists(db,"SELECT 1 FROM agent_worker WHERE identity=? AND enabled=1",actor)||access.isGlobalAdmin(actor)||!access.permissions(actor,"GLOBAL").equals(Set.of("AGENT_WORK"))||exists(db,"SELECT 1 FROM assignments a JOIN roles r ON a.role=r.id WHERE a.identity=? AND r.scope<>'GLOBAL'",actor)||exists(db,"SELECT 1 FROM memberships WHERE identity=?",actor))throw CommunityException.denied();exec(db,"UPDATE agent_worker SET last_seen=? WHERE identity=?",now(),actor);}
  private Map<String,Object> claim(String actor)throws Exception{return store.tx(db->{worker(db,actor);Map<String,Object> c=config(db);if(!bool(c,"enabled"))return Map.of("job",Map.of(),"pausedReason","Агент выключен");if(exists(db,"SELECT 1 FROM agent_job WHERE lease_owner=? AND state='LEASED' AND lease_until>?",actor,Long.toString(now())))return Map.of("job",Map.of(),"pausedReason","Рабочий узел уже выполняет задание");
    try(var q=db.prepareStatement("SELECT id,city FROM agent_job WHERE state='AVAILABLE' AND attempts<4 AND next_attempt<=? ORDER BY created LIMIT 1")){q.setLong(1,now());try(var r=q.executeQuery()){if(!r.next())return Map.of("job",Map.of(),"pausedReason","");String id=r.getString(1),city=r.getString(2);List<Map<String,Object>>sources=sources(db,city,true);if(sources.isEmpty()){exec(db,"UPDATE agent_job SET state='COMPLETE' WHERE id=?",id);return Map.of("job",Map.of(),"pausedReason","");}List<Map<String,Object>> dueSources=new ArrayList<>();Set<String> selectedHosts=new HashSet<>();for(Map<String,Object> source:sources){String host=URI.create(text(source,"url",2048)).getHost();if(!selectedHosts.add(host)||exists(db,"SELECT 1 FROM agent_host WHERE host=? AND next_fetch>?",host,Long.toString(now())))continue;dueSources.add(source);if(dueSources.size()==20)break;}sources=dueSources;if(sources.isEmpty())return Map.of("job",Map.of(),"pausedReason","Ожидание лимита обращения к источнику");
      long reserve=reservation(c);long maxTokens=number(c,"maxOutputTokens",128,4096);exec(db,"INSERT OR IGNORE INTO agent_budget VALUES(?,0,0,0)",day());try(var b=db.prepareStatement("SELECT * FROM agent_budget WHERE day=?")){b.setString(1,day());try(var br=b.executeQuery()){br.next();if(br.getLong("charged")+reserve>number(c,"dailyBudgetMicros",0,1000000000)||br.getLong("requests")+1>number(c,"dailyRequestLimit",1,10000)||br.getLong("tokens")+INPUT_RESERVATION+maxTokens>number(c,"dailyTokenLimit",100000,1000000000))return Map.of("job",Map.of(),"pausedReason","Достигнут дневной бюджет или лимит запросов");}}
      exec(db,"UPDATE agent_budget SET charged=charged+?,requests=requests+1,tokens=tokens+? WHERE day=?",reserve,INPUT_RESERVATION+maxTokens,day());for(Map<String,Object> source:sources)exec(db,"INSERT INTO agent_host(host,next_fetch) VALUES(?,?) ON CONFLICT(host) DO UPDATE SET next_fetch=excluded.next_fetch",URI.create(text(source,"url",2048)).getHost(),now()+number(source,"minIntervalMinutes",15,10080)*60000);String token=token();Map<String,Object> payload=new LinkedHashMap<>();payload.put("id",id);payload.put("cityId",city);payload.put("sources",sources);payload.put("modelPolicy",c);payload.put("policyRevision",revision(db));payload.put("maxInputBytes",90000);payload.put("leaseUntil",now()+600000);exec(db,"UPDATE agent_job SET state='LEASED',attempts=attempts+1,lease_owner=?,lease_hash=?,lease_until=?,revision=?,reserved=?,day=?,payload=? WHERE id=?",actor,hash(token),now()+600000,revision(db),reserve,day(),AgentJson.bytes(payload),id);payload.put("leaseToken",token);return Map.of("job",payload,"pausedReason","");}}
  });}
  private Map<String,Object> complete(String actor,Map<String,Object>d)throws Exception{return store.tx(db->{worker(db,actor);keys(d,Set.of("jobId","leaseToken","observations","analysis","inputTokens","outputTokens","fetchedSourceIds"));Job j=job(db,actor,d);if(j.state.equals("COMPLETE"))return Map.of("accepted",true,"duplicate",true);if(j.revision!=revision(db))throw new CommunityException("STALE_POLICY","Политика изменилась; результат отклонён");Map<String,Object> c=config(db);if(!bool(c,"enabled"))throw CommunityException.denied();
    List<Map<String,Object>> observations=maps(d.get("observations"),200);validateObservations(j.payload,observations);Map<String,Object> analysis=map(d.get("analysis"));if(!analysis.keySet().equals(Set.of("candidates")))throw CommunityException.invalid();List<Map<String,Object>> suggestions=maps(analysis.get("candidates"),10);if(count(db,"agent_candidate")+suggestions.size()>100000)throw limit();int accepted=0;for(Map<String,Object> suggestion:suggestions){Map<String,Object> draft=validateCandidate(suggestion,observations,j.payload,c);String dedupe=text(draft,"dedupe",64);if(exists(db,"SELECT 1 FROM agent_candidate WHERE dedupe=?",dedupe))continue;boolean seen=false;for(String evidence:strings(draft.get("sources"),10))seen|=exists(db,"SELECT 1 FROM agent_seen_evidence WHERE url=?",evidence);if(seen)continue;String candidate=UUID.randomUUID().toString();exec(db,"INSERT INTO agent_candidate(id,dedupe,job,state,draft,created) VALUES(?,?,?,'PENDING',?,?)",candidate,dedupe,j.id,AgentJson.bytes(draft),now());for(String evidence:strings(draft.get("sources"),10))exec(db,"INSERT INTO agent_seen_evidence VALUES(?,?)",evidence,candidate);accepted++;}
    Set<String> fetched=strings(d.get("fetchedSourceIds"),20);Set<String> allowed=new HashSet<>();for(Map<String,Object>s:maps(j.payload.get("sources"),20))allowed.add(text(s,"id",36));if(!allowed.containsAll(fetched))throw CommunityException.invalid();for(String source:fetched)exec(db,"UPDATE agent_source SET last_fetch=? WHERE id=?",now(),source);
    long in=number(d,"inputTokens",0,INPUT_RESERVATION),out=number(d,"outputTokens",0,number(c,"maxOutputTokens",128,4096));settle(db,j,c,in,out);exec(db,"UPDATE agent_job SET state='COMPLETE',lease_until=0,result=? WHERE id=?",AgentJson.bytes(Map.of("observations",observations)),j.id);exec(db,"UPDATE agent_city SET last_success=? WHERE id=?",now(),text(j.payload,"cityId",160));diagnostic(db,"JOB_COMPLETE","Публичные источники обработаны; предложений: "+accepted);return Map.of("accepted",true,"candidateCount",accepted);});}
  private Map<String,Object> fail(String actor,Map<String,Object>d)throws Exception{return store.tx(db->{worker(db,actor);keys(d,Set.of("jobId","leaseToken","reason"));Job j=job(db,actor,d);if(j.state.equals("COMPLETE"))return Map.of("accepted",true);String reason=text(d,"reason",64);if(!Set.of("SOURCE_UNAVAILABLE","MODEL_UNAVAILABLE","INVALID_MODEL_RESPONSE","CANCELLED","POLICY_REJECTED").contains(reason))throw CommunityException.invalid();exec(db,"UPDATE agent_job SET state=CASE WHEN attempts>=4 THEN 'FAILED' ELSE 'AVAILABLE' END,next_attempt=?,lease_until=0,last_error=? WHERE id=?",now()+Math.min(3600000,60000L*(1L<<Math.min(j.attempts,5))),reason,j.id);diagnostic(db,"JOB_RETRY",reason);return Map.of("accepted",true);});}
  private record Job(String id,String state,long revision,long reserved,String day,int attempts,Map<String,Object>payload){}
  private Job job(Connection db,String actor,Map<String,Object>d)throws Exception{String id=uuid(text(d,"jobId",36)),token=text(d,"leaseToken",64);try(var q=db.prepareStatement("SELECT * FROM agent_job WHERE id=? AND lease_owner=? AND lease_hash=?")){q.setString(1,id);q.setString(2,actor);q.setString(3,hash(token));try(var r=q.executeQuery()){if(!r.next()||!Set.of("LEASED","COMPLETE").contains(r.getString("state"))||r.getString("state").equals("LEASED")&&r.getLong("lease_until")<=now())throw CommunityException.missing();return new Job(id,r.getString("state"),r.getLong("revision"),r.getLong("reserved"),r.getString("day"),r.getInt("attempts"),AgentJson.object(r.getBytes("payload"),262144));}}}
  private record Pending(String id,String token,long revision,Map<String,Object>draft,Map<String,Object>payload,List<Map<String,Object>>observations,Reservation editorialReservation){}
  private record Reservation(String day,long amount,Map<String,Object>policy){}
  /** Independent public evidence fetch occurs outside the DB lock; the final authority check is atomic. */
  public void drainOutbox()throws Exception{for(int n=0;n<20;n++){
    Pending pending=store.tx(db->{Map<String,Object>c=config(db);if(!bool(c,"enabled"))return null;exec(db,"UPDATE agent_candidate SET state='PENDING',verify_token='' WHERE state='VERIFYING' AND verify_until<?",now());
      try(var q=db.createStatement();var r=q.executeQuery("SELECT a.id,a.draft,j.payload,j.result,a.verify_attempts FROM agent_candidate a JOIN agent_job j ON j.id=a.job WHERE a.state='PENDING' ORDER BY a.created LIMIT 100")){while(r.next()){String id=r.getString(1),token=UUID.randomUUID().toString();Map<String,Object>draft=AgentJson.object(r.getBytes(2),32768),payload=AgentJson.object(r.getBytes(3),262144);byte[]result=r.getBytes(4);List<Map<String,Object>>observations=result==null?List.of():maps(AgentJson.object(result,262144).get("observations"),200);
        String publisher=text(c,"publisherIdentity",64);if(!access.has(publisher,"NEWS_CREATE","GLOBAL"))return null;if(Boolean.TRUE.equals(draft.get("autoPublish"))&&!access.has(publisher,"NEWS_PUBLISH","GLOBAL"))return null;
        boolean currentPolicy=number(payload,"policyRevision",1,Long.MAX_VALUE)==revision(db);if(!currentPolicy||r.getInt(5)>=3)draft.put("autoPublish",false);
        if(Boolean.TRUE.equals(draft.get("autoPublish"))&&evidenceVerifier instanceof CentralEvidenceVerifier central&&!central.hasFreshSources(payload,observations,draft)){Set<String>urls=strings(draft.get("sources"),10),sourceIds=new HashSet<>();for(Map<String,Object>o:observations)if(urls.contains(o.get("url")))sourceIds.add(text(o,"sourceId",36));List<Map<String,Object>>proofSources=new ArrayList<>();boolean ready=true;for(Map<String,Object>source:maps(payload.get("sources"),20))if(sourceIds.contains(source.get("id"))){String host=URI.create(text(source,"url",2048)).getHost();if(exists(db,"SELECT 1 FROM agent_host WHERE host=? AND next_fetch>?",host,Long.toString(now())))ready=false;proofSources.add(source);}if(!ready)continue;for(Map<String,Object>source:proofSources)exec(db,"INSERT INTO agent_host(host,next_fetch) VALUES(?,?) ON CONFLICT(host) DO UPDATE SET next_fetch=excluded.next_fetch",URI.create(text(source,"url",2048)).getHost(),now()+number(source,"minIntervalMinutes",15,10080)*60000);}
        Reservation reservation=null;if(Boolean.TRUE.equals(draft.get("autoPublish"))&&evidenceVerifier instanceof TrustedEditorialVerifier){reservation=reserveEditorial(db,c);if(reservation==null){draft.put("autoPublish",false);draft.put("verified",false);}}exec(db,"UPDATE agent_candidate SET state='VERIFYING',verify_token=?,verify_until=?,verify_attempts=verify_attempts+1 WHERE id=?",token,now()+300000,id);return new Pending(id,token,number(payload,"policyRevision",1,Long.MAX_VALUE),draft,payload,observations,reservation);}return null;}
    });if(pending==null)break;
    EvidenceProof proof;
    try{proof=Boolean.TRUE.equals(pending.draft.get("autoPublish"))?evidenceVerifier.verify(pending.payload,pending.observations,pending.draft):new EvidenceProof(false,"EDITORIAL_REQUIRED",List.of());}catch(Exception e){proof=new EvidenceProof(false,"CENTRAL_PROOF_UNAVAILABLE",List.of());}
    EvidenceProof checked=proof;boolean keepGoing=store.tx(db->{if(!exists(db,"SELECT 1 FROM agent_candidate WHERE id=? AND state='VERIFYING' AND verify_token=?",pending.id,pending.token))return true;Map<String,Object>c=config(db);if(!bool(c,"enabled")){exec(db,"UPDATE agent_candidate SET state='PENDING',verify_token='' WHERE id=?",pending.id);return false;}
      Map<String,Object>draft=new LinkedHashMap<>(pending.draft);boolean trustedModelRequired=evidenceVerifier instanceof TrustedEditorialVerifier;if(trustedModelRequired&&!checked.trustedSuggestion.isEmpty())try{draft=validateCandidate(checked.trustedSuggestion,pending.observations,pending.payload,c);}catch(Exception invalid){draft.put("autoPublish",false);draft.put("verified",false);}boolean verified=checked.verified&&Boolean.TRUE.equals(draft.get("verified"))&&pending.revision==revision(db)&&(!trustedModelRequired||!checked.trustedSuggestion.isEmpty());draft.put("verified",verified);draft.put("autoPublish",verified&&bool(c,"autoPublish")&&Boolean.TRUE.equals(draft.get("autoPublish")));if(!bool(c,"allowGlobal")&&draft.get("distribution").equals("GLOBAL"))draft.put("distribution","CITY");
      if(pending.editorialReservation!=null){Reservation reserved=pending.editorialReservation;settle(db,new Job(pending.id,"VERIFYING",pending.revision,reserved.amount,reserved.day,0,Map.of()),reserved.policy,checked.inputTokens,checked.outputTokens);}if(!text(draft,"dedupe",64).equals(text(pending.draft,"dedupe",64))){if(exists(db,"SELECT 1 FROM agent_candidate WHERE dedupe=? AND id<>?",text(draft,"dedupe",64),pending.id)){exec(db,"UPDATE agent_candidate SET state='REJECTED',last_error='DUPLICATE_CENTRAL_RESULT',verify_token='' WHERE id=?",pending.id);return true;}exec(db,"UPDATE agent_candidate SET dedupe=? WHERE id=?",text(draft,"dedupe",64),pending.id);}String publisher=text(c,"publisherIdentity",64);try{access.require(publisher,"NEWS_CREATE","GLOBAL");if(Boolean.TRUE.equals(draft.get("autoPublish"))){access.require(publisher,"NEWS_PUBLISH","GLOBAL");if(draft.get("distribution").equals("GLOBAL"))access.require(publisher,"NEWS_GLOBAL_PUBLISH","GLOBAL");}Map<String,Object>result=sink.submit(publisher,draft);String state=Objects.toString(result.get("state"),"SUBMITTED");exec(db,"UPDATE agent_candidate SET state=?,content_id=?,proof=?,verify_token='',draft=? WHERE id=?",state.equals("PUBLISHED")?"PUBLISHED":"REVIEW",Objects.toString(result.get("id"),""),AgentJson.bytes(Map.of("verified",verified,"reason",checked.reason,"receipts",checked.receipts)),AgentJson.bytes(draft),pending.id);return true;}catch(CommunityException e){exec(db,"UPDATE agent_candidate SET state=?,verify_token='',last_error=? WHERE id=?",Set.of("INVALID","CONFLICT").contains(e.code())?"REJECTED":"PENDING",e.code(),pending.id);return Set.of("INVALID","CONFLICT").contains(e.code());}
    });if(!keepGoing)break;
  }}
  private void validateObservations(Map<String,Object>payload,List<Map<String,Object>>observations)throws Exception{Map<String,Map<String,Object>> allowed=new HashMap<>();for(Map<String,Object>s:maps(payload.get("sources"),20))allowed.put(text(s,"id",36),s);int total=0;for(Map<String,Object>o:observations){keys(o,Set.of("sourceId","sourceGroup","official","cityId","title","text","url","publishedAt","publicSource"));Map<String,Object>s=allowed.get(text(o,"sourceId",36));if(s==null||!bool(o,"publicSource")||!text(o,"sourceGroup",120).equals(text(s,"independenceGroup",120))||bool(o,"official")!=bool(s,"official")||!text(o,"cityId",160).equals(text(s,"cityId",160)))throw CommunityException.invalid();sourceUrl(text(o,"url",2048));text(o,"title",300);total+=text(o,"text",24000).getBytes(StandardCharsets.UTF_8).length;text(o,"publishedAt",40);if(total>85000)throw CommunityException.invalid();}}
  private Map<String,Object> validateCandidate(Map<String,Object>s,List<Map<String,Object>> observations,Map<String,Object>payload,Map<String,Object>c)throws Exception{
    keys(s,Set.of("title","summary","cityId","eventDate","significance","confidence","contradictions","citations"));String title=text(s,"title",300),summary=text(s,"summary",2000),city=city(text(s,"cityId",160)),event=text(s,"eventDate",10),significance=text(s,"significance",20);if(title.isBlank()||summary.isBlank()||title.indexOf('<')>=0||summary.indexOf('<')>=0||!city.equals(text(payload,"cityId",160))||!Set.of("ORDINARY","IMPORTANT").contains(significance))throw CommunityException.invalid();LocalDate date;try{date=LocalDate.parse(event);}catch(Exception e){throw CommunityException.invalid();}LocalDate today=LocalDate.now(store.clock());if(date.isBefore(today.minusDays(14))||date.isAfter(today.plusDays(365)))throw CommunityException.invalid();Object confidence=s.get("confidence");if(!(confidence instanceof Number number)||!Double.isFinite(number.doubleValue())||number.doubleValue()<0||number.doubleValue()>1)throw CommunityException.invalid();
    if(!(s.get("citations") instanceof List<?> citations)||citations.isEmpty()||citations.size()>10)throw CommunityException.invalid();Set<Integer>seen=new HashSet<>();Set<String>groups=new TreeSet<>(),urls=new TreeSet<>(),independentTexts=new HashSet<>();boolean dated=true,copy=false;for(Object index:citations){if(!(index instanceof Number ni)||ni.doubleValue()!=ni.intValue()||ni.intValue()<0||ni.intValue()>=observations.size()||!seen.add(ni.intValue()))throw CommunityException.invalid();Map<String,Object>o=observations.get(ni.intValue());String normalizedText=normalize(text(o,"text",24000));if(independentTexts.add(normalizedText))groups.add(text(o,"sourceGroup",120));urls.add(text(o,"url",2048));String normalizedSummary=normalize(summary);copy|=normalizedSummary.length()>50&&(normalizedText.contains(normalizedSummary)||normalizedSummary.contains(normalizedText));try{Instant published=Instant.parse(text(o,"publishedAt",40));dated&=!published.isBefore(store.clock().instant().minus(Duration.ofDays(14)))&&!published.isAfter(store.clock().instant().plus(Duration.ofHours(2)));}catch(Exception e){dated=false;}}
    boolean verified=groups.size()>=2&&urls.size()>=2&&dated&&!copy&&!bool(s,"contradictions")&&number.doubleValue()>=0.90;boolean auto=verified&&significance.equals("ORDINARY")&&bool(c,"autoPublish");Map<String,Object>draft=new LinkedHashMap<>();draft.put("title",title);draft.put("summary",summary);draft.put("sources",List.copyOf(urls));draft.put("sourceGroups",List.copyOf(groups));draft.put("cityId",city);draft.put("eventDate",date.atStartOfDay(ZoneOffset.UTC).toInstant().toString());draft.put("significance",significance.equals("ORDINARY")?"NORMAL":"IMPORTANT");draft.put("verified",verified);draft.put("autoPublish",auto);draft.put("distribution",bool(c,"allowGlobal")&&significance.equals("IMPORTANT")&&verified?"GLOBAL":"CITY");draft.put("dedupe",hash(city+"\n"+event+"\n"+normalize(title)));return draft;
  }
  private static String normalize(String s){return s.toLowerCase(Locale.ROOT).replaceAll("[^\\p{L}\\p{N}]+"," ").strip();}
  private Reservation reserveEditorial(Connection db,Map<String,Object>c)throws Exception{long reserve=reservation(c),maxTokens=number(c,"maxOutputTokens",128,4096);exec(db,"INSERT OR IGNORE INTO agent_budget VALUES(?,0,0,0)",day());try(var q=db.prepareStatement("SELECT charged,requests,tokens FROM agent_budget WHERE day=?")){q.setString(1,day());try(var r=q.executeQuery()){r.next();if(r.getLong(1)+reserve>number(c,"dailyBudgetMicros",0,1000000000)||r.getLong(2)+1>number(c,"dailyRequestLimit",1,10000)||r.getLong(3)+INPUT_RESERVATION+maxTokens>number(c,"dailyTokenLimit",100000,1000000000))return null;}}exec(db,"UPDATE agent_budget SET charged=charged+?,requests=requests+1,tokens=tokens+? WHERE day=?",reserve,INPUT_RESERVATION+maxTokens,day());return new Reservation(day(),reserve,Map.copyOf(c));}
  private static long reservation(Map<String,Object>c)throws Exception{return price(INPUT_RESERVATION,number(c,"inputMicrosPerMillion",0,1000000000))+price(number(c,"maxOutputTokens",128,4096),number(c,"outputMicrosPerMillion",0,1000000000));}
  private static long price(long tokens,long rate){return Math.floorDiv(Math.addExact(Math.multiplyExact(tokens,rate),999999),1000000);}
  private void settle(Connection db,Job job,Map<String,Object>c,long input,long output)throws Exception{if(input==0&&output==0)return;long actual=price(input,number(c,"inputMicrosPerMillion",0,1000000000))+price(output,number(c,"outputMicrosPerMillion",0,1000000000));if(actual>job.reserved)throw CommunityException.invalid();exec(db,"UPDATE agent_budget SET charged=charged-?,tokens=tokens-? WHERE day=?",job.reserved-actual,INPUT_RESERVATION+number(c,"maxOutputTokens",128,4096)-input-output,job.day);}
  private void diagnostic(Connection db,String kind,String detail)throws SQLException{exec(db,"INSERT INTO agent_diagnostic(created,kind,detail) VALUES(?,?,?)",now(),kind,detail);exec(db,"DELETE FROM agent_diagnostic WHERE id NOT IN (SELECT id FROM agent_diagnostic ORDER BY id DESC LIMIT 2000)");}
  private long now(){return store.clock().millis();}private String day(){return LocalDate.now(store.clock()).toString();}
  private String token(){byte[] b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
  private static String hash(String s)throws Exception{return CommunityStore.hex(CommunityStore.hash(s.getBytes(StandardCharsets.UTF_8)));}
  private static String city(String s)throws CommunityException{if(!s.matches("[a-z]{2}/[a-z0-9_-]{1,64}/[a-z0-9_-]{1,80}"))throw CommunityException.invalid();return s;}
  private static String uuid(String s)throws CommunityException{try{if(!UUID.fromString(s).toString().equals(s))throw CommunityException.invalid();return s;}catch(IllegalArgumentException e){throw CommunityException.invalid();}}
  private static void sourceUrl(String s)throws CommunityException{try{URI u=URI.create(s);String host=u.getHost();if(!u.getScheme().equals("https")||host==null||u.getRawUserInfo()!=null||u.getRawFragment()!=null||u.getPort()!=-1&&u.getPort()!=443||host.equals("localhost")||host.endsWith(".local")||host.endsWith(".onion")||host.indexOf('.')<0||host.matches("[0-9.]+"))throw CommunityException.invalid();}catch(IllegalArgumentException|NullPointerException e){throw CommunityException.invalid();}}
  private static String text(Map<String,Object>m,String k,int max)throws Exception{return AgentJson.text(m,k,max);}private static long number(Map<String,Object>m,String k,long min,long max)throws Exception{return AgentJson.number(m,k,min,max);}private static boolean bool(Map<String,Object>m,String k)throws Exception{return AgentJson.bool(m,k);}
  private static void keys(Map<String,Object>m,Set<String>allowed)throws CommunityException{if(!allowed.containsAll(m.keySet()))throw CommunityException.invalid();}
  @SuppressWarnings("unchecked")private static Map<String,Object>map(Object o)throws CommunityException{if(!(o instanceof Map<?,?> m)||m.keySet().stream().anyMatch(k->!(k instanceof String)))throw CommunityException.invalid();return (Map<String,Object>)m;}
  private static List<Map<String,Object>>maps(Object o,int max)throws CommunityException{if(!(o instanceof List<?> l)||l.size()>max)throw CommunityException.invalid();List<Map<String,Object>>out=new ArrayList<>();for(Object v:l)out.add(map(v));return out;}
  private static Set<String>strings(Object o,int max)throws CommunityException{if(!(o instanceof List<?>l)||l.size()>max)throw CommunityException.invalid();Set<String>s=new HashSet<>();for(Object v:l)if(v instanceof String t&&t.length()<=2048)s.add(t);else throw CommunityException.invalid();return s;}
  private static CommunityException limit(){return new CommunityException("LIMIT","Достигнут предел очереди или хранилища агента");}
  private static void exec(Connection db,String sql,Object...args)throws SQLException{try(var q=db.prepareStatement(sql)){for(int n=0;n<args.length;n++)q.setObject(n+1,args[n]);q.executeUpdate();}}
  private static boolean exists(Connection db,String sql,String...args)throws SQLException{return AccessControl.exists(db,sql,args);}private static long count(Connection db,String table)throws SQLException{if(!Set.of("agent_job","agent_source","agent_city","agent_candidate").contains(table))throw new IllegalArgumentException();try(var s=db.createStatement();var r=s.executeQuery("SELECT count(*) FROM "+table)){r.next();return r.getLong(1);}}
  private static long countWhere(Connection db,String table,String column,String value)throws SQLException{if(!Set.of("agent_job","agent_candidate").contains(table)||!column.equals("state"))throw new IllegalArgumentException();try(var q=db.prepareStatement("SELECT count(*) FROM "+table+" WHERE state=?")){q.setString(1,value);try(var r=q.executeQuery()){r.next();return r.getLong(1);}}}
  private static void ensureColumn(Connection db,String table,String column,String definition)throws SQLException{boolean found=false;try(var q=db.createStatement();var r=q.executeQuery("PRAGMA table_info("+table+")")){while(r.next())found|=r.getString("name").equals(column);}if(!found)try(var q=db.createStatement()){q.execute("ALTER TABLE "+table+" ADD COLUMN "+column+" "+definition);}}
  @Override public synchronized void close(){if(scheduler!=null){scheduler.shutdownNow();scheduler=null;}pageCursors.close();if(libraryLinks!=null)libraryLinks.close();if(evidenceVerifier instanceof AutoCloseable closable)try{closable.close();}catch(Exception ignored){}}
}
